def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.2))

    prev_bids = []
    rich_aggressive = 0
    desperate_count = 0
    zeroish_count = 0

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) <= 1.0:
                zeroish_count += 1
            if float(bid) >= 85.0 and opp.get('budget', 0) >= 80:
                rich_aggressive += 1
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    abundant_supply = supply >= 22

    if hp <= 2 or no_water >= 2:
        base = 66.0 if not tight_supply else 69.0
    elif hp <= 4 or no_water >= 1:
        base = 52.0 if abundant_supply else 58.0
    else:
        if abundant_supply:
            base = 18.0
        elif tight_supply:
            base = 34.0
        else:
            base = 26.0

    if highest_prev >= 95.0:
        if hp >= 5 and no_water == 0:
            base = min(base, 22.0 if abundant_supply else 28.0)
        else:
            base = max(base, 60.0)
    elif highest_prev >= 70.0:
        if hp >= 5 and no_water == 0:
            base = max(base, min(45.0, highest_prev * 0.55))
        else:
            base = max(base, min(64.0, highest_prev * 0.78))
    elif highest_prev > 0.0:
        target = highest_prev + 2.0
        if abundant_supply:
            target -= 3.0
        base = max(base, target)

    if rich_aggressive >= 2 and hp >= 5 and no_water == 0:
        base = min(base, 24.0 if abundant_supply else 30.0)

    if desperate_count >= 2 and (hp <= 4 or no_water >= 1):
        base = max(base, 61.0)

    if zeroish_count >= len(alive_opponents) - 1 and len(alive_opponents) > 0:
        base = min(base, 8.0 if hp >= 5 and no_water == 0 else 20.0)

    if day >= 8:
        if hp <= 4 or no_water >= 1:
            base = max(base, 60.0)
        else:
            base = max(base, 32.0)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 25.0
    affordable = max(0.0, budget - reserve_floor)
    if hp <= 2 or no_water >= 2:
        affordable = budget

    bid = min(base, affordable if affordable > 0 else budget)

    if hp >= 6 and no_water == 0 and avg_prev >= 90.0 and abundant_supply:
        bid = min(bid, 16.0)

    if bid < 0.0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        bid = DAILY_SALARY * 0.35
        return min(my_budget, bid)

    # Extract yesterday bids from immediate previous_trace
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Identify likely dominant opponent from yesterday: highest bid among alive
    dominant_prev = 0.0
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is None:
            continue
        try:
            fb = float(b)
        except Exception:
            continue
        if fb >= dominant_prev:
            dominant_prev = fb

    # Supply pressure: with medium supply, Cindy likely tries to secure water early.
    # Target: bid slightly above dominant yesterday bid when my hp is healthy.
    supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_factor = max(0.0, min(1.0, supply_factor))

    # Base urgency
    urgent = 0
    if my_hp <= 2.0:
        urgent = 2
    elif my_hp <= 4.0:
        urgent = 1
    if my_no_water_days >= 2:
        urgent = max(urgent, 2)

    # Decide aggressiveness
    # If dominant_prev was high (Cindy-like), we counter slightly above it; else conserve.
    if dominant_prev >= DAILY_SALARY * 0.85:
        # Counter window: only if we can afford it and we need water.
        if my_budget <= 0:
            return 0.0
        counter = dominant_prev + (2.0 + 3.0 * supply_factor)
        # If urgent, raise closer to dominant; if not urgent, keep tight.
        if urgent >= 2:
            bid = min(counter, dominant_prev + 8.0)
        else:
            bid = min(counter, dominant_prev + 4.0)
    else:
        # No strong leader yesterday: bid around a fraction of salary adjusted by supply.
        bid = DAILY_SALARY * (0.45 + 0.25 * supply_factor)
        if urgent >= 2:
            bid = DAILY_SALARY * (0.75 + 0.1 * supply_factor)

    # Final clamps
    bid = max(0.0, bid)
    if my_budget < bid:
        bid = my_budget

    # If supply is very low, avoid overbidding late in episode; if very high, bid slightly more.
    # Episode length is fixed at 10, so day 10 is last: be more conservative then.
    if day >= 9:
        bid *= 0.85

    return float(min(my_budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    yesterday_active_bids = []
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None and prev['bid'] > 0:
                yesterday_active_bids.append(prev['bid'])

    current_bid = DAILY_SALARY * 0.5

    if yesterday_active_bids:
        highest_prev_bid = max(yesterday_active_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] > 2:
                current_bid = min(my_status['budget'], highest_prev_bid * 0.95)
            else:
                current_bid = min(my_status['budget'], highest_prev_bid * 1.05 + 1)
        elif highest_prev_bid > DAILY_SALARY * 0.3:
            current_bid = max(current_bid, highest_prev_bid + 1.0)

    if my_status['hp'] <= 2:
        current_bid = max(current_bid, DAILY_SALARY * 0.95)
    elif my_status['no_water_days'] > 0:
        current_bid = max(current_bid, DAILY_SALARY * 0.8)

    days_left = EPISODE_DAYS - day_context['day']
    if days_left <= 2:
        current_bid = max(current_bid, DAILY_SALARY * 0.75)

    num_water_units_from_supply = int(day_context['supply'] // WATER_REQ)
    num_potential_bidders = len(alive_opponents) + 1

    if num_water_units_from_supply >= num_potential_bidders:
        if my_status['hp'] > 3:
            current_bid = min(current_bid, DAILY_SALARY * 0.4)
    elif num_water_units_from_supply < num_potential_bidders and num_water_units_from_supply > 0:
        current_bid = max(current_bid, DAILY_SALARY * 0.6)
    else:
        if my_status['hp'] <= 2:
            current_bid = max(current_bid, DAILY_SALARY * 0.98)
        else:
            current_bid = min(current_bid, DAILY_SALARY * 0.6)

    final_bid = max(0.0, min(my_status['budget'], current_bid))
    return final_bid

